class Database:
    def __init__(self, connection, postgres):
        self.connection = connection
        self.postgres = postgres

    def execute(self, sql, params=()):
        if self.postgres:
            sql = sql.replace("?", "%s")
        return self.connection.execute(sql, params)

    def lock_bookings(self):
        if self.postgres:
            self.connection.execute("SELECT pg_advisory_xact_lock(2026102901)")
        else:
            self.connection.execute("BEGIN IMMEDIATE")


@contextmanager
def database():
    url = os.environ.get("DATABASE_URL", "").strip()
    if os.environ.get("RENDER", "").lower() == "true" and not url:
        raise RuntimeError("DATABASE_URL est absente de Render > Environment")

    if url:
        import psycopg
        from psycopg.rows import dict_row
        connection = psycopg.connect(url, row_factory=dict_row, connect_timeout=15)
    else:
        Path(DB_PATH).parent.mkdir(parents=True, exist_ok=True)
        connection = sqlite3.connect(DB_PATH, timeout=15)
        connection.row_factory = sqlite3.Row

    db = Database(connection, postgres=bool(url))
    try:
        if url:
            connection.execute("SELECT pg_advisory_xact_lock(2026102900)")
        db.execute(
            "CREATE TABLE IF NOT EXISTS bookings ("
            "id TEXT PRIMARY KEY, token TEXT UNIQUE, "
            'start TEXT, "end" TEXT, '
            "name TEXT, email TEXT, phone TEXT, vehicle TEXT, "
            "services TEXT, price INTEGER, "
            "status TEXT DEFAULT 'confirmed')"
        )
        # Migration additive : ne supprime et ne remplace AUCUN rendez-vous existant.
        if db.postgres:
            db.execute("ALTER TABLE bookings ADD COLUMN IF NOT EXISTS estimate_max INTEGER")
            db.execute("ALTER TABLE bookings ADD COLUMN IF NOT EXISTS confirmation_status TEXT DEFAULT 'approved'")
        else:
            known = {row[1] for row in db.execute('PRAGMA table_info(bookings)').fetchall()}
            if 'estimate_max' not in known:
                db.execute('ALTER TABLE bookings ADD COLUMN estimate_max INTEGER')
            if 'confirmation_status' not in known:
                db.execute("ALTER TABLE bookings ADD COLUMN confirmation_status TEXT DEFAULT 'approved'")
        db.execute("CREATE TABLE IF NOT EXISTS garage_closures (day TEXT PRIMARY KEY, reason TEXT NOT NULL DEFAULT '')")
        # Montants en centimes : migrations additives compatibles Neon/SQLite.
        for column in ('price_cents', 'estimate_max_cents', 'welcome_discount'):
            if db.postgres:
                db.execute(f'ALTER TABLE bookings ADD COLUMN IF NOT EXISTS {column} INTEGER')
            elif column not in {r[1] for r in db.execute('PRAGMA table_info(bookings)').fetchall()}:
                db.execute(f'ALTER TABLE bookings ADD COLUMN {column} INTEGER')
        connection.commit()
        yield db
        connection.commit()
    except BaseException:
        connection.rollback()
        raise
    finally:
        connection.close()


def require_admin(fn):
    @wraps(fn)
    def wrapper(*args, **kwargs):
        secret = os.environ.get("ADMIN_TOKEN", "")
        header = request.headers.get("Authorization", "")
        given = header[7:] if header.startswith("Bearer ") else ""
        if len(secret) < 24 or not hmac.compare_digest(secret, given):
            abort(401, "Acces garage refuse.")
        return fn(*args, **kwargs)
    return wrapper


def json_body():
    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        abort(400, "Formulaire invalide.")
    return data


def chosen_services(ids):
    if (
        not isinstance(ids, list)
        or not ids
        or any(not isinstance(i, str) or i not in CATALOGUE for i in ids)
        or len(ids) != len(set(ids))
    ):
        abort(400, "Selection de prestations invalide.")
    return [CATALOGUE[i] for i in ids]


def checked_slot(value, minutes):
    try:
        start = datetime.strptime(value, "%Y-%m-%dT%H:%M").replace(tzinfo=PARIS)
    except (ValueError, TypeError):
        abort(400, "Date invalide.")

    end = start + timedelta(minutes=minutes)
    now = datetime.now(PARIS)
    if (
        start <= now + timedelta(hours=1)
        or start > now + timedelta(days=90)
        or start.weekday() == 6
        or start.minute not in (0, 30)
        or start.hour < 9
        or end.date() != start.date()
        or end.hour > 18
        or (end.hour == 18 and end.minute > 0)
        # Pause de midi 12h30-13h30. À adapter dans ce fichier.
        or (start.hour * 60 + start.minute < 13 * 60 + 30
            and end.hour * 60 + end.minute > 12 * 60 + 30)
    ):
        abort(400, "Creneau indisponible (lundi-samedi, 9h-18h).")

    return start.strftime("%Y-%m-%dT%H:%M"), end.strftime("%Y-%m-%dT%H:%M")


def occupied(db, start, end):
    return db.execute(
        "SELECT 1 FROM bookings WHERE status='confirmed' "
        'AND start < ? AND "end" > ?',
        (end, start),
    ).fetchone() is not None


@app.after_request
def secure_headers(response):
    # Le site est français : empêcher la traduction des marques et codes.
    if response.mimetype == "text/html" and not response.direct_passthrough:
        html = response.get_data(as_text=True)
        def french_root(match):
            attrs = re.sub(r"\s+(?:lang|translate)\s*=\s*(?:\"[^\"]*\"|'[^']*'|[^\s>]+)", "", match.group(1), flags=re.I)
            return '<html lang="fr" translate="no"' + attrs + '>'
        html = re.sub(r"<html\b([^>]*)>", french_root, html, count=1, flags=re.I)
        html = re.sub(r"<head\b[^>]*>", lambda m: m.group() + '<meta name="google" content="notranslate">', html, count=1, flags=re.I)
        response.set_data(html)
        response.headers["Content-Language"] = "fr"
    response.headers["X-Content-Type-Options"] = "nosniff"
    response.headers["X-Frame-Options"] = "DENY"
    response.headers["Referrer-Policy"] = "no-referrer"
    response.headers["Content-Security-Policy"] = (
        "default-src 'self'; img-src 'self' data:; "
        "style-src 'self'; script-src 'self'; frame-ancestors 'none'; "
        "base-uri 'self'; form-action 'self'"
    )
    if request.path.startswith("/api"):
        response.headers["Cache-Control"] = "no-store"
    return response


