@app.get("/")
def home():
    # Charge le site existant et ajoute le module sans changer index.html.
    html = (SITE_ROOT / "index.html").read_text(encoding="utf-8")
    html = re.sub(r'<div class="hero">.*?(?=<div class="wrap section" id="catalogue">)', FUTURE_HERO, html, count=1, flags=re.S)
    html = html.replace('K2 Motor — Atelier mécanique', 'K2 Motor — Le garage au pas de votre porte')
    html = html.replace('K2 Motor, atelier mécanique. Choisissez vos prestations et réservez votre rendez-vous en ligne.', 'K2 Motor, le garage au pas de votre porte. Estimez votre entretien automobile et réservez votre intervention.')
    html = html.replace('L’entretien automobile, simplement.', 'Le garage au pas de votre porte.')
    html = html.replace('01 / L’ATELIER À LA CARTE', '01 / VOTRE ENTRETIEN, À LA CARTE')
    html = html.replace('<div class="promise">', REVIEWS_SECTION + '<div class="promise">', 1)
    # Conserve les formulaires et identifiants utilisés par le site existant.
    html = re.sub(r'(<a\b[^>]*class="brand"[^>]*>).*?(</a>)',
                  r'\1<img src="/k2-logo.svg" alt="K2 Motor, garage automobile">\2',
                  html, flags=re.IGNORECASE | re.DOTALL)
    html = html.replace('</nav>', '<a href="/suivi">Suivi +</a></nav>', 1)
    html = html.replace('<div id="admin-area" hidden>', '<p><a class="outline" href="/pro">Ouvrir le nouveau tableau de bord du garage</a></p><div id="admin-area" hidden>', 1)
    html = html.replace('Des prix clairs. Votre temps respecté.', 'Estimations à partir de. Devis confirmé avant intervention.')
    offer = '<aside class="k2-welcome-banner" aria-label="Offre de bienvenue"><strong>BIENVENUE CHEZ K2 MOTOR · −10 %</strong><span>Sur votre première intervention, hors déplacement. Remise vérifiée à la réservation.</span><a href="#" id="k2-welcome-open">Estimer mon tarif →</a></aside>'
    html = re.sub(r'(</header\s*>)', lambda m: m.group() + offer, html, count=1, flags=re.I) if re.search(r'</header\s*>', html, re.I) else re.sub(r'(<body\b[^>]*>)', lambda m: m.group() + offer, html, count=1, flags=re.I)
    css = '<link rel="stylesheet" href="/k2-estimation.css"><link rel="stylesheet" href="/k2-brand.css">'
    js = '<script src="/k2-estimation.js" defer></script>' 
    if re.search(r"</head\s*>", html, flags=re.IGNORECASE):
        html = re.sub(r"</head\s*>", lambda m: css + "\n" + m.group(), html, count=1, flags=re.IGNORECASE)
    else:
        html = css + html
    if re.search(r"</body\s*>", html, flags=re.IGNORECASE):
        html = re.sub(r"</body\s*>", lambda m: js + "\n" + m.group(), html, count=1, flags=re.IGNORECASE)
    else:
        html += js
    return Response(html, mimetype="text/html")


