def discounted_cents(amount, eligible):
    return int((Decimal(str(amount)) * (90 if eligible else 100)).quantize(Decimal('1'), rounding=ROUND_HALF_UP))


def welcome_quote(quote, eligible):
    return {**quote, 'subtotal_min': quote['min'], 'subtotal_max': quote['max'],
            'discount_percent': 10 if eligible else 0,
            'min': discounted_cents(quote['min'], eligible) / 100,
            'max': discounted_cents(quote['max'], eligible) / 100}


def phone_identity(value):
    digits = re.sub(r'\D', '', value or '')
    if digits.startswith('0033'):
        digits = '0' + digits[4:]
    elif digits.startswith('33') and len(digits) == 11:
        digits = '0' + digits[2:]
    return digits


def first_visit(db, email, phone):
    # Une réservation active réserve aussi l'offre ; une annulation la libère.
    rows = db.execute("SELECT email, phone FROM bookings WHERE status != 'cancelled'").fetchall()
    return not any((row['email'] or '').strip().casefold() == email.strip().casefold()
                   or phone_identity(row['phone']) == phone_identity(phone) for row in rows)


def public_booking(row):
    result = dict(row)
    result.pop('token', None)
    if result.get('price_cents') is not None:
        result['price'] = result['price_cents'] / 100
    if result.get('estimate_max_cents') is not None:
        result['estimate_max'] = result['estimate_max_cents'] / 100
    return result


