@app.get("/api/slots")
def available_slots():
    selected = chosen_services(request.args.get("services", "").split(","))
    duration = sum(s["minutes"] for s in selected)
    day = request.args.get("date", "")
    try:
        datetime.strptime(day, "%Y-%m-%d")
    except ValueError:
        abort(400, "Date invalide.")

    result = []
    with database() as db:
        if db.execute("SELECT 1 FROM garage_closures WHERE day=?", (day,)).fetchone():
            return jsonify([])
        existing = db.execute(
            "SELECT start, \"end\" FROM bookings WHERE status='confirmed' "
            'AND start < ? AND "end" > ?',
            (day + "T23:59", day + "T00:00"),
        ).fetchall()
        for minute in range(9 * 60, 18 * 60, 30):
            candidate = f"{day}T{minute // 60:02d}:{minute % 60:02d}"
            try:
                start, end = checked_slot(candidate, duration)
            except Exception as error:
                if getattr(error, "code", None) == 400:
                    continue
                raise
            if not any(row["start"] < end and row["end"] > start for row in existing):
                result.append(candidate)
    return jsonify(result)


@app.post("/api/bookings")
def create_booking():
    data = json_body()
    selected = chosen_services(data.get("services"))
    for field in ("name", "email", "phone"):
        value = data.get(field)
        if not isinstance(value, str) or not 2 <= len(value.strip()) <= 150:
            abort(400, "Coordonnees incompletes ou trop longues.")
        data[field] = value.strip()

    if (
        not re.fullmatch(r"[^\s@]+@[^\s@]+\.[^\s@]+", data["email"])
        or not re.fullmatch(r"[+\d ().-]{8,25}", data["phone"])
    ):
        abort(400, "Email ou telephone invalide.")

    # Les anciennes réservations restent compatibles avec app.js d'origine.
    # Le module véhicule, lui, enregistre un prix « à partir de » recalculé
    # côté serveur (jamais un prix dicté par le navigateur).
    if "vehicle_profile" in data:
        quote = vehicle_estimate(data["vehicle_profile"], selected)
        vehicle = quote["vehicle"]
        vehicle_text = (
            f'{vehicle["brand"]} {vehicle["model"]} '
            f'({vehicle["year"]}, {FUEL_LABELS[vehicle["fuel"]]})'
        )
        booking_price = quote["min"]
        estimate_max = quote["max"]
    else:
        vehicle_text = data.get("vehicle")
        if not isinstance(vehicle_text, str) or not 2 <= len(vehicle_text.strip()) <= 150:
            abort(400, "Véhicule manquant ou trop long.")
        vehicle_text = vehicle_text.strip()
        booking_price = sum(TARIFS_VEHICULES['prestations'].get(s['id'], {}).get('min', s['price']) for s in selected)
        estimate_max = None

    start, end = checked_slot(
        data.get("start"), sum(s["minutes"] for s in selected)
    )
    ident = secrets.token_hex(5).upper()
    token = secrets.token_urlsafe(32)
    with database() as db:
        db.lock_bookings()
        if db.execute("SELECT 1 FROM garage_closures WHERE day=?", (start[:10],)).fetchone():
            abort(409, "Le garage est fermé ce jour-là. Choisissez une autre date.")
        eligible = first_visit(db, data["email"], data["phone"])
        final_min = discounted_cents(booking_price, eligible)
        final_max = discounted_cents(estimate_max, eligible) if estimate_max is not None else None
        if occupied(db, start, end):
            abort(409, "Ce creneau vient d'etre reserve. Choisissez-en un autre.")
        db.execute(
            "INSERT INTO bookings "
            '(id, token, start, "end", name, email, phone, vehicle, services, price, estimate_max, confirmation_status, price_cents, estimate_max_cents, welcome_discount) '
            "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            (
                ident, token, start, end, data["name"], data["email"],
                data["phone"], vehicle_text,
                json.dumps([s["id"] for s in selected]),
                booking_price, estimate_max, 'pending', final_min, final_max, 10 if eligible else 0,
            ),
        )
    result = {"id": ident, "token": token, "confirmation_status": "pending",
              "discount_percent": 10 if eligible else 0, "price": final_min / 100,
              "estimate_max": final_max / 100 if final_max is not None else None}
    result["email_sent"] = send_booking_mail(
        data["email"], data["name"], ident, token, start, vehicle_text,
        final_min / 100, final_max / 100 if final_max is not None else None, eligible
    )
    if "vehicle_profile" in data:
        result["estimate"] = welcome_quote(quote, eligible)
    return jsonify(result), 201


@app.post("/api/lookup")
def lookup_booking():
    token = json_body().get("token", "")
    if not isinstance(token, str):
        abort(400, "Code invalide.")
    with database() as db:
        row = db.execute(
            "SELECT * FROM bookings WHERE token=?", (token,)
        ).fetchone()
    if row is None:
        abort(404, "Reservation introuvable.")
    result = public_booking(row)
    return jsonify(result)


@app.post("/api/cancel")
def cancel_booking():
    token = json_body().get("token", "")
    if not isinstance(token, str):
        abort(400, "Code invalide.")
    with database() as db:
        row = db.execute(
            "SELECT * FROM bookings WHERE token=?", (token,)
        ).fetchone()
        if row is None:
            abort(404, "Reservation introuvable.")
        if row["status"] != "confirmed":
            abort(409, "Ce rendez-vous n'est plus actif.")
        if row["start"] <= datetime.now(PARIS).strftime("%Y-%m-%dT%H:%M"):
            abort(400, "Ce rendez-vous est deja passe.")
        db.execute(
            "UPDATE bookings SET status='cancelled' WHERE token=?",
            (token,),
        )
        email, ident, start_time = row['email'], row['id'], row['start']
    sent = send_email(email, "K2 Motor - Annulation de votre rendez-vous", f"Votre rendez-vous {ident} du {start_time.replace('T', ' à ')} a été annulé.")
    return jsonify(ok=True, email_sent=sent)


@app.get("/api/admin/bookings")
@require_admin
def admin_bookings():
    with database() as db:
        rows = db.execute(
            'SELECT id, start, "end", name, email, phone, vehicle, '
            "services, price, estimate_max, status, confirmation_status, price_cents, estimate_max_cents, welcome_discount FROM bookings ORDER BY start DESC"
        ).fetchall()
    return jsonify([public_booking(row) for row in rows])


@app.post("/api/admin/status")
@require_admin
def admin_status():
    data = json_body()
    if (
        data.get("status") not in ("cancelled", "completed")
        or not isinstance(data.get("id"), str)
    ):
        abort(400, "Demande invalide.")
    with database() as db:
        updated = db.execute(
            "UPDATE bookings SET status=? WHERE id=?",
            (data["status"], data["id"]),
        )
        if updated.rowcount == 0:
            abort(404, "Rendez-vous introuvable.")
    return jsonify(ok=True)



