def send_email(recipient, subject, body):
    """Return True only when the SMTP server actually accepts the email."""
    host = os.environ.get('SMTP_HOST', '').strip()
    sender = os.environ.get('SMTP_FROM', '').strip()
    if not host or not sender:
        return False
    try:
        port = int(os.environ.get('SMTP_PORT', '587'))
        username = os.environ.get('SMTP_USER', '')
        password = os.environ.get('SMTP_PASSWORD', '')
        message = EmailMessage()
        message['From'] = sender
        message['To'] = recipient
        message['Subject'] = subject
        message.set_content(body)
        if port == 465:
            with smtplib.SMTP_SSL(host, port, timeout=8) as server:
                if username and password:
                    server.login(username, password)
                server.send_message(message)
        else:
            with smtplib.SMTP(host, port, timeout=8) as server:
                server.ehlo()
                server.starttls()
                server.ehlo()
                if username and password:
                    server.login(username, password)
                server.send_message(message)
        return True
    except Exception:
        app.logger.exception('SMTP indisponible : message non envoyé')
        return False


def send_booking_mail(email, name, ident, token, start, vehicle, price_min, price_max, eligible=False):
    range_label = f'de {price_min} à {price_max} €' if price_max else f'à partir de {price_min} €'
    body = (
        f'Bonjour {name},\n\nVotre créneau K2 Motor a été réservé. '
        'Le devis définitif reste à valider par le garage.\n\n'
        f'Référence : {ident}\nRendez-vous : {start.replace("T", " à ")}\n'
        f'Véhicule : {vehicle}\nEstimation non contractuelle : {range_label}\n' +
        ('Remise de bienvenue de 10 % incluse.\n' if eligible else '') +
        f'Code confidentiel : {token}\n\n'
        'Suivi : https://k2-motor.onrender.com/suivi\n\n'
        'Ne partagez pas votre code de réservation.\nK2 Motor'
    )
    return send_email(email, 'K2 Motor - Créneau réservé', body)


