def valid_closure_day(raw):
    if not isinstance(raw, str) or not re.fullmatch(r'\d{4}-\d{2}-\d{2}', raw):
        abort(400, 'Date de fermeture invalide.')
    try:
        datetime.strptime(raw, '%Y-%m-%d')
    except ValueError:
        abort(400, 'Date de fermeture invalide.')
    return raw


@app.post('/api/admin/closures')
@require_admin
def close_day():
    data = json_body()
    day = valid_closure_day(data.get('day'))
    reason = data.get('reason', '')
    if not isinstance(reason, str) or len(reason) > 120:
        abort(400, 'Motif trop long.')
    with database() as db:
        db.lock_bookings()
        # Ne supprime aucun ancien rendez-vous. Affiche un avertissement au garage.
        booked = db.execute('SELECT COUNT(*) AS n FROM bookings WHERE start >= ? AND start < ? AND status=?',
                            (day+'T00:00', day+'T23:59', 'confirmed')).fetchone()['n']
        db.execute('DELETE FROM garage_closures WHERE day=?', (day,))
        db.execute('INSERT INTO garage_closures(day,reason) VALUES(?,?)', (day, reason.strip()))
    return jsonify(ok=True, existing_reservations=booked,
                   warning=(f'{booked} rendez-vous déjà pris ce jour : contactez-les avant toute fermeture.' if booked else None))


@app.delete('/api/admin/closures')
@require_admin
def reopen_day():
    day = valid_closure_day(json_body().get('day'))
    with database() as db:
        db.execute('DELETE FROM garage_closures WHERE day=?', (day,))
    return jsonify(ok=True)


@app.post('/api/admin/confirm')
@require_admin
def approve_booking():
    ident = json_body().get('id')
    if not isinstance(ident, str) or not re.fullmatch(r'[A-F0-9]{10}', ident):
        abort(400, 'Référence invalide.')
    with database() as db:
        row = db.execute('SELECT * FROM bookings WHERE id=?', (ident,)).fetchone()
        if row is None:
            abort(404, 'Rendez-vous introuvable.')
        if row['status'] != 'confirmed':
            abort(409, 'Ce rendez-vous est annulé ou déjà terminé.')
        db.execute("UPDATE bookings SET confirmation_status='approved' WHERE id=?", (ident,))
        email,start = row['email'],row['start']
    sent=send_email(email, 'K2 Motor - Rendez-vous validé',
              f'Bonjour,\n\nVotre rendez-vous K2 Motor n° {ident} du {start.replace("T", " à ")} a été validé par le garage.\n\nÀ bientôt,\nK2 Motor')
    return jsonify(ok=True, email_sent=sent)



